<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'';if($action==='start'){$name=trim($_POST['swimmer_name']??'');$phone=trim($_POST['phone']??'');$mins=max(5,min(480,(int)($_POST['duration_minutes']??60)));$customer=(int)($_POST['customer_id']??0)?:null;if($name){$st=$pdo->prepare("INSERT INTO swim_sessions(customer_id,swimmer_name,phone,duration_minutes,started_at,ends_at,status,created_by) VALUES(?,?,?,?,NOW(),DATE_ADD(NOW(),INTERVAL ? MINUTE),'active',?)");$st->execute([$customer,$name,$phone,$mins,current_user()['id']]);flash('Swim session started for '.$name.'.');}}elseif($action==='finish'){$id=(int)$_POST['id'];$pdo->prepare("UPDATE swim_sessions SET status='completed',finished_at=NOW() WHERE id=? AND status='active'")->execute([$id]);flash('Swim session completed.');}redirect('swimmers.php');}
$rows=$pdo->query("SELECT * FROM swim_sessions WHERE status='active' ORDER BY ends_at")->fetchAll();$history=$pdo->query("SELECT * FROM swim_sessions WHERE status<>'active' ORDER BY id DESC LIMIT 12")->fetchAll();$customers=$pdo->query("SELECT id,name,phone FROM customers ORDER BY name")->fetchAll();layout_start('Swim sessions','swimmers');?>
<div class="page-actions"><div><p class="muted">Track entry times, session duration, and expiry alerts.</p><p class="tiny muted">Timers run from the saved start/end timestamps.</p></div><button class="btn primary" onclick="document.getElementById('sessionForm').classList.toggle('hidden')">＋ Start session</button></div><section class="panel form-panel hidden" id="sessionForm"><h3>New swimmer session</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="start"><label>Swimmer name *<input name="swimmer_name" required></label><label>Phone<input name="phone"></label><label>Existing customer<select name="customer_id"><option value="">Not linked</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></label><label>Duration<select name="duration_minutes"><option value="30">30 minutes</option><option value="60" selected>1 hour</option><option value="90">90 minutes</option><option value="120">2 hours</option><option value="180">3 hours</option></select></label><div class="form-actions"><button class="btn primary">Start timer</button></div></form></section><div class="section-title-row"><div><h3>Active swimmers</h3><p class="muted">Live remaining time</p></div><span class="badge success"><?=count($rows)?> active</span></div><div class="session-grid"><?php foreach($rows as $r):?><article class="session-card" data-ends="<?=strtotime($r['ends_at'])*1000?>"><div class="session-card-top"><span class="session-pulse"></span><span class="badge soft">IN POOL</span><span class="session-id">#<?=str_pad($r['id'],4,'0',STR_PAD_LEFT)?></span></div><h3><?=h($r['swimmer_name'])?></h3><p class="muted"><?=h($r['phone']?:'No phone added')?> · <?=$r['duration_minutes']?> min session</p><div class="timer-readout" data-timer>--:--:--</div><div class="timer-progress"><span style="width:50%"></span></div><div class="session-foot"><small>Ends <?=date('h:i A',strtotime($r['ends_at']))?></small><form method="post" onsubmit="return confirm('Finish this session?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="finish"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small secondary">Finish</button></form></div></article><?php endforeach;if(!$rows):?><div class="empty large">No active swimmers. Start a session when a swimmer enters the pool.</div><?php endif;?></div><section class="panel table-panel"><div class="panel-head"><div><h3>Recent session history</h3><p class="muted">Completed and expired sessions</p></div></div><div class="table-wrap"><table><thead><tr><th>Swimmer</th><th>Duration</th><th>Started</th><th>Finished</th><th>Status</th></tr></thead><tbody><?php foreach($history as $r):?><tr><td><?=h($r['swimmer_name'])?></td><td><?=$r['duration_minutes']?> min</td><td><?=date('d M, h:i A',strtotime($r['started_at']))?></td><td><?= $r['finished_at']?date('d M, h:i A',strtotime($r['finished_at'])):'—'?></td><td><span class="badge soft"><?=h($r['status'])?></span></td></tr><?php endforeach;if(!$history):?><tr><td colspan="5" class="empty">No session history yet.</td></tr><?php endif;?></tbody></table></div></section><script src="assets/js/timers.js"></script><?php layout_end();?>
